CREATE FUNCTION assert_entitlement_quota(org uuid,delta_rooms integer DEFAULT 0,delta_properties integer DEFAULT 0,delta_staff integer DEFAULT 0) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE e public.organization_entitlements%ROWTYPE;n integer;BEGIN
IF org IS DISTINCT FROM public.current_org() OR NOT EXISTS(SELECT 1 FROM public.memberships WHERE organization_id=org AND user_id=public.current_actor() AND revoked_at IS NULL) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0404';END IF;
IF delta_rooms<0 OR delta_properties<0 OR delta_staff<0 THEN RAISE EXCEPTION 'VALIDATION_ERROR' USING ERRCODE='P0422';END IF;
SELECT * INTO e FROM public.organization_entitlements WHERE organization_id=org FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'ENTITLEMENT_NOT_CONFIGURED' USING ERRCODE='P0409';END IF;
IF e.plan_kind='development' AND coalesce(current_setting('app.runtime_environment',true),'') NOT IN ('development','test') THEN RAISE EXCEPTION 'ENTITLEMENT_NOT_CONFIGURED' USING ERRCODE='P0409';END IF;
IF e.state IN ('restricted','cancelled') OR (e.valid_until IS NOT NULL AND clock_timestamp()>=e.valid_until AND (e.grace_until IS NULL OR clock_timestamp()>=e.grace_until)) OR(e.state='grace' AND(e.grace_until IS NULL OR clock_timestamp()>=e.grace_until)) THEN RAISE EXCEPTION 'SUBSCRIPTION_RESTRICTED' USING ERRCODE='P0403';END IF;
SELECT count(*) INTO n FROM public.rooms WHERE organization_id=org AND archived_at IS NULL;IF n+delta_rooms>e.room_limit THEN RAISE EXCEPTION 'QUOTA_EXCEEDED' USING ERRCODE='P0409';END IF;
SELECT count(*) INTO n FROM public.properties WHERE organization_id=org AND archived_at IS NULL;IF n+delta_properties>e.property_limit THEN RAISE EXCEPTION 'QUOTA_EXCEEDED' USING ERRCODE='P0409';END IF;
SELECT count(*) INTO n FROM public.memberships WHERE organization_id=org AND revoked_at IS NULL;IF n+delta_staff>e.staff_limit THEN RAISE EXCEPTION 'QUOTA_EXCEEDED' USING ERRCODE='P0409';END IF;
END $$;
REVOKE ALL ON FUNCTION assert_entitlement_quota(uuid,integer,integer,integer) FROM PUBLIC;GRANT EXECUTE ON FUNCTION assert_entitlement_quota(uuid,integer,integer,integer) TO kost_app;
CREATE FUNCTION enforce_inventory_quota() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN
IF TG_TABLE_NAME='memberships' THEN IF NEW.revoked_at IS NOT NULL THEN RETURN NEW;END IF;IF TG_OP='UPDATE' AND OLD.revoked_at IS NULL THEN RETURN NEW;END IF;IF NOT EXISTS(SELECT 1 FROM public.organization_entitlements WHERE organization_id=NEW.organization_id) AND NEW.role='Owner' AND EXISTS(SELECT 1 FROM public.organizations WHERE id=NEW.organization_id AND created_by=NEW.user_id) AND (SELECT count(*) FROM public.memberships WHERE organization_id=NEW.organization_id)=1 THEN RETURN NEW;END IF;
ELSE IF NEW.archived_at IS NOT NULL THEN RETURN NEW;END IF;IF TG_OP='UPDATE' AND OLD.archived_at IS NULL THEN RETURN NEW;END IF;END IF;
PERFORM public.assert_entitlement_quota(NEW.organization_id,0,0,0);RETURN NEW;END $$;
CREATE TRIGGER rooms_quota AFTER INSERT OR UPDATE OF archived_at ON rooms FOR EACH ROW EXECUTE FUNCTION enforce_inventory_quota();
CREATE TRIGGER properties_quota AFTER INSERT OR UPDATE OF archived_at ON properties FOR EACH ROW EXECUTE FUNCTION enforce_inventory_quota();
CREATE TRIGGER staff_quota AFTER INSERT OR UPDATE OF revoked_at ON memberships FOR EACH ROW EXECUTE FUNCTION enforce_inventory_quota();
REVOKE ALL ON FUNCTION enforce_inventory_quota() FROM PUBLIC;
CREATE FUNCTION snapshot_room_type() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN IF TG_OP='INSERT' THEN IF NEW.version<>1 THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='P0409';END IF;ELSE IF NEW.id<>OLD.id OR NEW.organization_id<>OLD.organization_id OR NEW.property_id<>OLD.property_id OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='P0409';END IF;END IF;IF public.current_actor() IS NULL THEN RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE='P0403';END IF;INSERT INTO public.room_type_versions(organization_id,property_id,type_id,version,name,default_capacity,default_facilities,actor_id) VALUES(NEW.organization_id,NEW.property_id,NEW.id,NEW.version,NEW.name,NEW.default_capacity,NEW.default_facilities,public.current_actor());RETURN NEW;END $$;
CREATE TRIGGER type_snapshot AFTER INSERT OR UPDATE ON room_types FOR EACH ROW EXECUTE FUNCTION snapshot_room_type();REVOKE ALL ON FUNCTION snapshot_room_type() FROM PUBLIC;
CREATE FUNCTION guard_room_shape() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE levels integer;BEGIN IF TG_OP='UPDATE' THEN IF NEW.id<>OLD.id OR NEW.organization_id<>OLD.organization_id OR NEW.property_id<>OLD.property_id OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='P0409';END IF;END IF;SELECT floors INTO levels FROM public.properties WHERE organization_id=NEW.organization_id AND id=NEW.property_id AND archived_at IS NULL;IF levels IS NULL OR NEW.floor>levels THEN RAISE EXCEPTION 'PROPERTY_CONFIGURATION_REQUIRED' USING ERRCODE='P0409';END IF;IF NEW.condition='ready' THEN RAISE EXCEPTION 'READINESS_WORKFLOW_REQUIRED' USING ERRCODE='P0409';END IF;RETURN NEW;END $$;
CREATE TRIGGER room_shape BEFORE INSERT OR UPDATE ON rooms FOR EACH ROW EXECUTE FUNCTION guard_room_shape();REVOKE ALL ON FUNCTION guard_room_shape() FROM PUBLIC;
CREATE FUNCTION guard_property_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN IF NEW.id<>OLD.id OR NEW.organization_id<>OLD.organization_id OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='P0409';END IF;IF NEW.floors IS NOT NULL AND EXISTS(SELECT 1 FROM public.rooms WHERE organization_id=NEW.organization_id AND property_id=NEW.id AND floor>NEW.floors) THEN RAISE EXCEPTION 'FLOOR_IN_USE' USING ERRCODE='P0409';END IF;RETURN NEW;END $$;
CREATE TRIGGER property_profile_guard BEFORE UPDATE ON properties FOR EACH ROW EXECUTE FUNCTION guard_property_profile();REVOKE ALL ON FUNCTION guard_property_profile() FROM PUBLIC;
